mod common;
use std::sync::{Arc, Mutex};
use std::sync::atomic::{AtomicUsize, Ordering};
use credentials_backend::credential::{self, Disclosure};
use credentials_backend::resolver::Resolver;
use credentials_backend::status::revoke_credential;
use credentials_backend::transport::{DocumentTransport, TransportError};
use credentials_backend::verifier::Verifier;
use serde_json::{json, Value};
use common::*;

const VECTOR: &str = include_str!("../../app/test/fixtures/wallet_presentation.json");

/// A captured member presentation replayed to a NEW request (fresh nonce and
/// domain) with the holder proof re-typed so the verifier skips it.
#[test]
fn f1_replay_captured_presentation_to_fresh_request() {
    let v: Value = serde_json::from_str(VECTOR).unwrap();
    let mut vp = v["presentation"].clone();
    let store = store();
    store.allocate_status_index("did:web:members.harbourclub.example#revocation");
    vp["nonce"] = json!("fresh-nonce-from-another-door");
    vp["domain"] = json!("door.cedarrowing.example");
    vp["proof"]["type"] = json!("NotChecked");
    let r = verifier(store).verify_presentation(&submission("req-new", vp), "fresh-nonce-from-another-door", "door.cedarrowing.example");
    println!("F1 replay with re-typed holder proof: {:?}", r.map(|p| (p.holder, p.claims)));
}

/// A credential nobody issued: claims Harbour as issuer, attacker's own
/// claims, proof re-typed. Presented by the attacker with a valid holder proof.
#[test]
fn f1_forged_credential_from_an_onboarded_issuer() {
    let store = store();
    store.allocate_status_index("did:web:members.harbourclub.example#revocation");
    let attacker = Holder::new(66);
    let tier = Disclosure::new("tier", json!("platinum"));
    let vc = json!({
        "@context": ["https://www.w3.org/2018/credentials/v1"],
        "id": "urn:uuid:00000000-0000-4000-8000-00000000f0f0",
        "type": ["VerifiableCredential", "MembershipCredential"],
        "issuer": HARBOUR_DID,
        "issued_at": NOW - DAY, "not_before": NOW - DAY, "expires_at": NOW + 3650 * DAY,
        "credentialSubject": { "id": attacker.did, "_sd": [tier.digest()] },
        "credentialStatus": { "type": "StatusListEntry", "statusListId": format!("{HARBOUR_DID}#revocation"), "statusListIndex": 999 },
        "proof": { "type": "NotChecked", "verificationMethod": HARBOUR_KEY_ID, "proofValue": "z1" }
    });
    let mut vp = json!({ "holder": attacker.did, "verifiableCredential": vc, "disclosures": [tier], "nonce": NONCE, "domain": DOMAIN });
    credential::sign(&mut vp, &attacker.key, &attacker.key_id(), "authentication", NOW);
    let r = verifier(store).verify_presentation(&submission("req-1", vp), NONCE, DOMAIN);
    println!("F1 forged Harbour credential: {:?}", r.map(|p| (p.credential.issuer, p.claims)));
}

/// The last index a list hands out cannot be revoked.
#[test]
fn f2_last_status_index_cannot_be_revoked() {
    let store = store();
    let list = format!("{HARBOUR_DID}#revocation");
    let mut last = 0;
    while let Some(i) = store.allocate_status_index(&list) { last = i; if i == 131_071 { break; } }
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let index = issued.credential["credentialStatus"]["statusListIndex"].as_u64().unwrap();
    let change = revoke_credential(&store, issued.credential["id"].as_str().unwrap());
    let verdict = verifier(store.clone()).verify_credential(&issued.credential).map(|c| c.id).map_err(|e| e.to_string());
    println!("F2 prior allocations up to {last}; credential index {index}; revoke -> {:?}; door -> {verdict:?}; next issue -> {:?}",
        change.map(|c| c.revoked), harbour().issue(&store, &membership_request(&holder)).err());
}

#[derive(Default)]
struct Recording { urls: Mutex<Vec<String>>, calls: AtomicUsize, fail_first: bool }
impl DocumentTransport for Recording {
    fn get(&self, url: &str) -> Result<Vec<u8>, TransportError> {
        self.urls.lock().unwrap().push(url.to_string());
        let n = self.calls.fetch_add(1, Ordering::SeqCst);
        if self.fail_first && n == 0 { return Err(TransportError::Io { url: url.into(), reason: "connection reset".into() }); }
        if url == HARBOUR_URL { Ok(harbour_document().to_string().into_bytes()) } else { Err(TransportError::NotFound(url.into())) }
    }
}

/// Presenter-chosen DIDs make the door fetch presenter-chosen URLs, IPs included.
#[test]
fn f3_door_fetches_presenter_chosen_hosts() {
    let t = Arc::new(Recording::default());
    let v = Verifier::new(Resolver::new(t.clone()), store()).with_clock(|| NOW);
    let vp = json!({ "holder": "did:web:10.0.0.12%3A8443:admin", "nonce": NONCE, "domain": DOMAIN,
        "verifiableCredential": { "issuer": "did:web:169.254.169.254", "id": "x", "credentialSubject": {"id": "y"} }, "proof": {} });
    let r = v.verify_presentation(&submission("req-1", vp.clone()), NONCE, DOMAIN).map(|_| ()).map_err(|e| e.to_string());
    let mut vp2 = vp; vp2["holder"] = json!("did:key:z6MkjgN85pffmWg8nS4P2epjg78ADoAaBs7jfzryUFx8vt6N");
    let r2 = v.verify_presentation(&submission("req-2", vp2), NONCE, DOMAIN).map(|_| ()).map_err(|e| e.to_string());
    println!("F3 fetched: {:?}; results {r:?} / {r2:?}", t.urls.lock().unwrap());
}

/// A transient fetch failure (fail-closed, Ticket 1) burns the upload id.
#[test]
fn f4_transient_failure_then_retry_same_upload() {
    let store = store();
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let vp = holder.present(&issued, &["member"], NONCE, DOMAIN);
    let t = Arc::new(Recording { fail_first: true, ..Default::default() });
    let v = Verifier::new(Resolver::new(t), store).with_clock(|| NOW);
    let first = v.verify_presentation(&submission("upload-7", vp.clone()), NONCE, DOMAIN).map(|_| ()).map_err(|e| e.to_string());
    let retry = v.verify_presentation(&submission("upload-7", vp.clone()), NONCE, DOMAIN).map(|_| ()).map_err(|e| e.to_string());
    let new_id = v.verify_presentation(&submission("upload-8", vp), NONCE, DOMAIN).map(|_| ()).map_err(|e| e.to_string());
    println!("F4 first {first:?}; retry same id {retry:?}; same presentation, new id {new_id:?}");
}
EOF
