mod common;
use std::sync::Arc;
use std::time::{Duration, Instant as WallClock};
use credentials_backend::notifier::*;
use credentials_backend::settings::{Setting, SettingsStore};
use credentials_backend::status::StatusChange;
use credentials_backend::webhook::{Endpoint, HermeticTransport};
use serde_json::json;
use common::*;

fn change(tenant: &str) -> StatusChange {
    StatusChange { credential_id: "urn:uuid:1".into(), issuer: tenant.into(), status_list: "l".into(), status_index: 1, revoked: true }
}
fn rig() -> (Arc<SettingsStore>, Arc<HermeticTransport>, Arc<MemorySink>, Notifier) {
    let s = Arc::new(SettingsStore::new()); let t = Arc::new(HermeticTransport::new()); let k = Arc::new(MemorySink::default());
    let n = Notifier::new(s.clone(), t.clone(), k.clone()); (s, t, k, n)
}

/// CPU spent by the join as the subscriber count grows; every subscriber
/// answers at a distinct time, so every answer wakes the join.
#[tokio::test(start_paused = true)]
async fn f5_join_cpu_cost() {
    for n in [1_000usize, 2_000, 4_000, 8_000] {
        let (s, t, k, notifier) = rig();
        for i in 0..n {
            let url = format!("https://rp.example/{i}");
            s.put(Setting::new("tenant", &format!("webhook/{i:05}"), WEBHOOK_KIND, json!({ "url": url })));
            t.route(&url, Endpoint::slow(Duration::from_micros(100 + i as u64 * 400)));
        }
        let wall = WallClock::now();
        notifier.notify(&change("tenant")).await;
        let delivered = k.events().iter().filter(|e| matches!(e.outcome, Outcome::Delivered { .. })).count();
        println!("F5 n={n:>5}: CPU {:>7.2?} for the fan-out, {delivered} delivered", wall.elapsed());
    }
}

/// Two changes in flight on one notifier: A never reaches its subscribers
/// (lookup outlasts the budget), B is fine. What does health say after both?
#[tokio::test(start_paused = true)]
async fn f6_concurrent_changes_share_the_health_flag() {
    let (s, t, k, notifier) = rig();
    t.route_host("never.example", Endpoint::ok());
    for i in 0..17_000 { s.put(Setting::new("tenant-a", &format!("webhook/{i:05}"), WEBHOOK_KIND, json!({ "url": format!("https://never.example/{i}") }))); }
    tokio::join!(notifier.notify(&change("tenant-a")), async {
        tokio::time::sleep(Duration::from_millis(10)).await;
        notifier.notify(&change("tenant-b")).await
    });
    let canary: Vec<_> = k.events().into_iter().filter(|e| e.subscription == CANARY_ID).map(|e| (e.tenant, e.outcome)).collect();
    println!("F6 canary events {canary:?}; canary_healthy() = {}", notifier.canary_healthy());
}

/// A webhook setting the notifier can't read gets no delivery record.
#[tokio::test(start_paused = true)]
async fn f7_unreadable_webhook_setting_leaves_no_record() {
    let (s, t, k, notifier) = rig();
    t.route("https://ok.example/", Endpoint::ok());
    s.put(Setting::new("tenant", "webhook/ok", WEBHOOK_KIND, json!({ "url": "https://ok.example/" })));
    s.put(Setting::new("tenant", "webhook/typo", WEBHOOK_KIND, json!({ "uri": "https://rp.example/hook" })));
    s.put(Setting::new("tenant", "webhook/numeric", WEBHOOK_KIND, json!({ "url": 42 })));
    notifier.notify(&change("tenant")).await;
    println!("F7 recorded subscriptions: {:?}", k.events().iter().map(|e| e.subscription.as_str()).collect::<Vec<_>>());
}

/// The identical presentation, accepted twice under two upload ids.
#[test]
fn f8_same_presentation_accepted_twice() {
    let store = store();
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let vp = holder.present(&issued, &["member"], NONCE, DOMAIN);
    let v = verifier(store);
    let a = v.verify_presentation(&submission("upload-1", vp.clone()), NONCE, DOMAIN).is_ok();
    let b = v.verify_presentation(&submission("upload-2", vp), NONCE, DOMAIN).is_ok();
    println!("F8 first accepted={a}, identical resubmission accepted={b}");
}
EOF
cargo test --release --offline --test p4_notifier -- --nocapture --test-threads=1 2>&1 | grep -oE "F[0-9] .*|^error.*"

